const stuckProjects = $('Check Stuck Projects').first().json.rows || [];
const systemHealth = $input.first().json;

const issues = [];

if (stuckProjects.length > 0) {
  issues.push({
    type: 'stuck_projects',
    severity: 'high',
    count: stuckProjects.length,
    details: stuckProjects.map(p => ({
      id: p.id,
      title: p.title,
      state: p.state,
      idle_minutes: Math.round(p.idle_seconds / 60)
    }))
  });
}

if (systemHealth.status === 'degraded') {
  issues.push({
    type: 'system_degraded',
    severity: 'medium',
    details: systemHealth
  });
}

if (systemHealth.status === 'down') {
  issues.push({
    type: 'system_down',
    severity: 'critical',
    details: systemHealth
  });
}

if (systemHealth.disk_usage > 90) {
  issues.push({
    type: 'disk_space',
    severity: 'high',
    details: { usage: systemHealth.disk_usage + '%' }
  });
}

if (systemHealth.memory_usage > 90) {
  issues.push({
    type: 'memory_pressure',
    severity: 'high',
    details: { usage: systemHealth.memory_usage + '%' }
  });
}

return [{
  json: {
    issues: issues,
    total_issues: issues.length,
    stuck_projects: stuckProjects,
    system_health: systemHealth,
    timestamp: new Date().toISOString()
  }
}];

